package com.spaceagent.platform.artifact.infrastructure.memory;import com.spaceagent.platform.artifact.domain.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.stereotype.Repository;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
@Repository @ConditionalOnProperty(prefix="platform",name="persistence",havingValue="memory",matchIfMissing=true)public class InMemoryArtifactRepository implements ArtifactRepository{private final Map<String,Artifact> v=new ConcurrentHashMap<>();public void save(Artifact a){v.put(a.id(),a);}public Optional<Artifact> findById(String id){return Optional.ofNullable(v.get(id));}public List<Artifact> findByRunId(String id){return v.values().stream().filter(a->a.agentRunId().equals(id)).sorted(Comparator.comparing(Artifact::createdAt)).toList();}public List<Artifact> findByTaskId(String id){return v.values().stream().filter(a->a.taskId().equals(id)).sorted(Comparator.comparing(Artifact::createdAt)).toList();}}
